WITH subq1 AS ( WITH inner_cte AS ( SELECT scd.DEPARTMENT_NAME, scd.COURSE_LEVEL, COUNT(DISTINCT scd.COURSE) AS course_count, MIN(ccc.TOTAL_UNITS) AS min_total_units FROM SIS_COURSE_DESCRIPTION scd JOIN SIS_DEPARTMENT sd ON scd.DEPARTMENT = sd.DEPARTMENT_CODE JOIN CIS_COURSE_CATALOG ccc ON sd.DEPARTMENT_CODE = ccc.DEPARTMENT_CODE WHERE scd.IS_DEGREE_GRANTING = 'Y' AND ccc.TOTAL_UNITS > 6 GROUP BY scd.DEPARTMENT_NAME, scd.COURSE_LEVEL ) SELECT ic.DEPARTMENT_NAME, ic.COURSE_LEVEL, ic.course_count, ic.min_total_units, COUNT(DISTINCT CASE WHEN ccc.DESIGN_UNITS >= 3 THEN scd.COURSE END) AS courses_with_design_units_3_or_more FROM inner_cte ic JOIN SIS_COURSE_DESCRIPTION scd ON ic.DEPARTMENT_NAME = scd.DEPARTMENT_NAME AND ic.COURSE_LEVEL = scd.COURSE_LEVEL JOIN SIS_DEPARTMENT sd ON scd.DEPARTMENT = sd.DEPARTMENT_CODE JOIN CIS_COURSE_CATALOG ccc ON sd.DEPARTMENT_CODE = ccc.DEPARTMENT_CODE WHERE scd.IS_DEGREE_GRANTING = 'Y' AND ccc.TOTAL_UNITS > 6 GROUP BY ic.DEPARTMENT_NAME, ic.COURSE_LEVEL, ic.course_count, ic.min_total_units ), subq2 AS ( WITH inner_cte AS ( SELECT ACADEMIC_TERMS.ACADEMIC_YEAR, ACADEMIC_TERMS.ACADEMIC_YEAR_DESC, COURSE_CATALOG_SUBJECT_OFFERED.DEPARTMENT_NAME, COURSE_CATALOG_SUBJECT_OFFERED.SUBJECT_ID, COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS FROM ACADEMIC_TERMS JOIN COURSE_CATALOG_SUBJECT_OFFERED ON ACADEMIC_TERMS.TERM_CODE = COURSE_CATALOG_SUBJECT_OFFERED.EFFECTIVE_TERM_CODE WHERE ACADEMIC_TERMS.IS_REGULAR_TERM = 'Y' ), dept_stats AS ( SELECT ACADEMIC_YEAR, ACADEMIC_YEAR_DESC, DEPARTMENT_NAME, AVG(TOTAL_UNITS) AS avg_total_units, STDDEV(TOTAL_UNITS) AS stddev_total_units FROM inner_cte GROUP BY ACADEMIC_YEAR, ACADEMIC_YEAR_DESC, DEPARTMENT_NAME ) SELECT i.ACADEMIC_YEAR, i.ACADEMIC_YEAR_DESC, i.DEPARTMENT_NAME, i.SUBJECT_ID, i.TOTAL_UNITS, d.avg_total_units, d.stddev_total_units, (i.TOTAL_UNITS - d.avg_total_units) AS deviation_from_avg FROM inner_cte i JOIN dept_stats d ON i.ACADEMIC_YEAR = d.ACADEMIC_YEAR AND i.ACADEMIC_YEAR_DESC = d.ACADEMIC_YEAR_DESC AND i.DEPARTMENT_NAME = d.DEPARTMENT_NAME ORDER BY i.ACADEMIC_YEAR, i.DEPARTMENT_NAME, deviation_from_avg DESC ) SELECT s1.DEPARTMENT_NAME, s1.COURSE_LEVEL, s1.course_count, s1.min_total_units, s1.courses_with_design_units_3_or_more, s2.ACADEMIC_YEAR, s2.ACADEMIC_YEAR_DESC, s2.SUBJECT_ID, s2.TOTAL_UNITS, s2.avg_total_units, s2.stddev_total_units, s2.deviation_from_avg FROM subq1 s1 JOIN subq2 s2 ON s1.DEPARTMENT_NAME = s2.DEPARTMENT_NAME ORDER BY s1.DEPARTMENT_NAME, s1.COURSE_LEVEL, s2.ACADEMIC_YEAR, s2.SUBJECT_ID;